const body = $input.first().json.body || $input.first().json;

if (!body.documentId || !body.businessId) {
  throw new Error('Parámetros requeridos ausentes: documentId y businessId son obligatorios.');
}

const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidRegex.test(body.documentId)) {
  throw new Error(`documentId inválido: "${body.documentId}" no es un UUID. Asegúrate de enviar un UUID v4.`);
}

const mimeType = body.mimeType || 'application/pdf';
const fileUrl = body.fileUrl || '';
const originalFilename = body.originalFilename || 'documento';
const isPdf = mimeType.toLowerCase().includes('pdf') ||
              fileUrl.toLowerCase().split('?')[0].endsWith('.pdf') ||
              originalFilename.toLowerCase().endsWith('.pdf');

return {
  json: {
    documentId: body.documentId,
    businessId: body.businessId,
    storagePath: body.storagePath || '',
    originalFilename,
    mimeType,
    fileUrl,
    isPdf: Boolean(isPdf),
    modelOverride: body.model || body.modelOverride || null,
    detailOverride: body.detail || body.detailOverride || null,
    uploadedAt: body.uploadedAt || new Date().toISOString()
  }
};

const doc = $('Validate & Normalize Input').item.json;

if (!doc.fileUrl) {
  throw new Error('fileUrl ausente: no se puede analizar el documento.');
}

const systemPrompt = 'Eres un analizador fiscal especializado en facturas y tickets en España. Extrae los datos del documento en formato JSON estricto: {"supplier_name": string|null, "supplier_nif": string|null, "invoice_number": string|null, "date": "YYYY-MM-DD"|null, "base_amount": number|null, "vat_rate": number|null, "vat_amount": number|null, "total_amount": number|null, "category": string, "description": string, "confidence": number}. Categorías válidas: alimentacion, bebidas, limpieza, suministros, alquiler, mantenimiento, personal, servicios_profesionales, software, material_oficina, marketing, transporte, seguros, otros.';

const userContent = [
  { type: 'text', text: 'Extrae todos los datos fiscales de esta factura o recibo con alta precisión.' }
];

const model = doc.modelOverride || 'gpt-4o-mini';
const detailLevel = doc.detailOverride || 'high';

if (doc.isPdf) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (buf.length > 20 * 1024 * 1024) {
    throw new Error('El PDF supera el límite de 20 MB.');
  }
  const filename = doc.originalFilename.toLowerCase().endsWith('.pdf')
    ? doc.originalFilename
    : 'documento.pdf';
  userContent.push({
    type: 'file',
    file: {
      filename,
      file_data: 'data:application/pdf;base64,' + buf.toString('base64')
    }
  });
} else {
  userContent.push({
    type: 'image_url',
    image_url: { url: doc.fileUrl, detail: detailLevel }
  });
}

return [{
  json: {
    ...doc,
    selectedModel: model,
    selectedDetail: detailLevel,
    openaiBody: {
      model,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userContent }
      ],
      response_format: { type: 'json_object' },
      temperature: 0.1
    }
  }
}];

const docInfo = $('Validate & Normalize Input').item.json;
const reqInfo = $('Build OpenAI Request').item.json;
const openaiRaw = $input.first().json;

let parsed = {};
let parseFailed = false;
try {
  parsed = JSON.parse(openaiRaw.choices[0].message.content);
} catch (e) {
  parseFailed = true;
  parsed = { supplier_name: null, total_amount: null, confidence: 0.2 };
}

const base = Number(parsed.base_amount) || 0;
const vat = Number(parsed.vat_amount) || 0;
const total = Number(parsed.total_amount) || (base + vat) || 0;
const vatRaw = parsed.vat_rate;
const rate = (vatRaw !== null && vatRaw !== undefined && !isNaN(Number(vatRaw))) ? Number(vatRaw) : 10;

let status = 'EXTRACTED';
const warnings = [];

if (parseFailed) {
  warnings.push('La respuesta de OpenAI no se pudo interpretar.');
  status = 'NEEDS_REVIEW';
}

if (!parsed.supplier_name) {
  warnings.push('Proveedor no identificado con certeza.');
  status = 'NEEDS_REVIEW';
}

if (total <= 0) {
  warnings.push('Importe total no detectado o menor a cero.');
  status = 'NEEDS_REVIEW';
}

const confidence = parsed.confidence ?? (status === 'EXTRACTED' ? 0.95 : 0.60);
const usage = openaiRaw.usage || { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 };
const modelUsed = openaiRaw.model || reqInfo.selectedModel || 'gpt-4o-mini';

return {
  json: {
    documentId: docInfo.documentId,
    businessId: docInfo.businessId,
    status,
    confidence,
    warnings,
    modelUsed,
    usage,
    extracted: {
      supplier_name: parsed.supplier_name || 'Proveedor desconocido',
      supplier_nif: parsed.supplier_nif || null,
      invoice_number: parsed.invoice_number || null,
      date: parsed.date || new Date().toISOString().split('T')[0],
      base_amount: Math.round(base * 100) / 100,
      vat_rate: rate,
      vat_amount: Math.round(vat * 100) / 100,
      total_amount: Math.round(total * 100) / 100,
      category: parsed.category || 'otros',
      description: parsed.description || docInfo.originalFilename
    },
    rawPayload: openaiRaw
  }
};

